def build():
    seen = set()
    cases = []

    def add(items, source):
        for item in items:
            inp = item["input"]
            exp = item["expected"]
            if inp == exp:
                continue
            if inp in seen:
                continue
            seen.add(inp)
            cases.append({"input": inp, "expected": exp, "source": source})

    add(josdejong, "josdejong/jsonrepair")
    add(mangiucugna, "mangiucugna/json_repair")
    add(dirty_json, "RyanMarcus/dirty-json")

    with open("extracted_cases.json", "w") as f:
        json.dump(cases, f, indent=2, ensure_ascii=False)

    print(f"Total: {len(cases)} cases")
    sources = {}
    for c in cases:
        sources[c["source"]] = sources.get(c["source"], 0) + 1
    for s, n in sorted(sources.items()):
        print(f"  {s}: {n}")


if __name__ == "__main__":
    build()
